import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._queued = set()
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "closed": False,
        }
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        if ticket_id not in self._queued:
            priority = self._tickets[ticket_id]["priority"]
            rank = -self.PRIORITIES.index(priority)
            heapq.heappush(self._queue, (rank, ticket_id))
            self._queued.add(ticket_id)

    def next_ticket(self) -> int | None:
        while self._queue:
            _, ticket_id = heapq.heappop(self._queue)
            if ticket_id in self._queued:
                self._queued.remove(ticket_id)
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["closed"] = True
        self._queued.discard(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        if self._tickets[ticket_id]["closed"]:
            raise ValueError("Cannot reopen a closed ticket")
        self._enqueue(ticket_id)
